1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 40px 16px;
12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 520px; margin: 0 auto; }
17	  h1 { font-size: 28px; margin: 0 0 16px; }
18	  form { display: flex; gap: 8px; margin-bottom: 16px; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 10px 12px;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 8px;
26	    background: #fff;
27	  }
28	  input[type="text"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
29	  button {
30	    font: inherit;
31	    border: 0;
32	    border-radius: 8px;
33	    cursor: pointer;
34	  }
35	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
36	  .add:hover { background: #1d4ed8; }
37	  ul { list-style: none; margin: 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 12px;
42	    padding: 10px 12px;
43	    margin-bottom: 8px;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 8px;
47	  }
48	  .text { flex: 1; overflow-wrap: anywhere; }
49	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
50	  .delete:hover { background: #fee2e2; }
51	  .empty { color: #78716c; text-align: center; padding: 16px 0; }
52	</style>
53	</head>
54	<body>
55	<main>
56	  <h1>Todos</h1>
57	  <form id="todo-form">
58	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
59	    <button type="submit" class="add" data-testid="todo-add">Add</button>
60	  </form>
61	  <ul data-testid="todo-list"></ul>
62	  <p class="empty" hidden>No todos yet.</p>
63	</main>
64	<script>
65	(function () {
66	  var STORAGE_KEY = 'todos';
67	  var form = document.getElementById('todo-form');
68	  var input = document.querySelector('[data-testid="todo-input"]');
69	  var list = document.querySelector('[data-testid="todo-list"]');
70	  var empty = document.querySelector('.empty');
71	
72	  function load() {
73	    try {
74	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
75	      return Array.isArray(data) ? data : [];
76	    } catch (e) {
77	      return [];
78	    }
79	  }
80	
81	  function save() {
82	    try {
83	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
84	    } catch (e) {
85	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
86	    }
87	  }
88	
89	  function makeId() {
90	    if (window.crypto && typeof crypto.randomUUID === 'function') {
91	      return crypto.randomUUID();
92	    }
93	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
94	  }
95	
96	  var todos = load();
97	
98	  function render() {
99	    list.textContent = '';
100	    todos.forEach(function (todo) {
101	      var li = document.createElement('li');
102	      li.setAttribute('data-testid', 'todo-item');
103	      li.setAttribute('data-id', todo.id);
104	
105	      var text = document.createElement('span');
106	      text.className = 'text';
107	      text.setAttribute('data-testid', 'todo-text');
108	      text.textContent = todo.text;
109	
110	      var del = document.createElement('button');
111	      del.type = 'button';
112	      del.className = 'delete';
113	      del.setAttribute('data-testid', 'todo-delete');
114	      del.setAttribute('aria-label', 'Delete todo');
115	      del.textContent = 'Delete';
116	      del.addEventListener('click', function () { remove(todo.id); });
117	
118	      li.appendChild(text);
119	      li.appendChild(del);
120	      list.appendChild(li);
121	    });
122	    empty.hidden = todos.length > 0;
123	  }
124	
125	  function add(text) {
126	    todos.push({ id: makeId(), text: text, createdAt: Date.now() });
127	    save();
128	    render();
129	  }
130	
131	  function remove(id) {
132	    todos = todos.filter(function (t) { return t.id !== id; });
133	    save();
134	    render();
135	  }
136	
137	  form.addEventListener('submit', function (e) {
138	    e.preventDefault();
139	    var text = input.value.trim();
140	    if (!text) return;
141	    add(text);
142	    input.value = '';
143	    input.focus();
144	  });
145	
146	  render();
147	})();
148	</script>
149	</body>
150	</html>
