await p.locator('[data-testid=todo-item]', {hasText:'b'}).locator('[data-testid=todo-toggle]').check();
await p.locator('[data-testid=todo-item]', {hasText:'a'}).locator('[data-testid=todo-toggle]').check();
console.log('a,b done', await state());
await p.click('[data-testid=filter-active]'); console.log('active', await state());
await p.click('[data-testid=filter-completed]'); console.log('completed', await state());
await p.click('[data-testid=filter-all]');
await p.locator('[data-testid=todo-item]', {hasText:'b'}).locator('[data-testid=todo-toggle]').uncheck();
console.log('b undone', await state());
await p.reload(); console.log('reload', await state());
await b.close();
EOF
